import { cellText, codes, table } from './markdown-table.mjs';

const GENERATED =
  'Generated by `npm run audit:keywords` from the Bing Webmaster Tools API, one `GetKeywordStats` request per phrase it prices. Each phrase is built from the concept register and the glossary titles of `docs/SEMANTIC-CORE.md` through the templates in `keywords.templates` of `site/engine.config.json`, and a buyer prompt is never priced as written. Exact and Broad add up the weekly impressions Bing returned in the window: its exact-match and its broad-match count.';

const LIMITS =
  "Two limits hold for every figure here. Bing's index is smaller than Google's, so a phrase that reads 0 is weak evidence and never a veto. This audit prices phrases and never proposes one: Bing's related-keywords endpoint answers nothing for any phrase, so every phrase was built from the concepts and titles of the site itself.";

const NO_WINDOW = 'Bing returned no weekly row for any phrase, so this run has no window.';
const NOTHING_PRICED = 'No phrase was priced this run, so this run has no window.';

const COLUMNS = 'Weeks counts the weekly rows Bing returned, and 0 means Bing holds no data for the phrase.';
const MEASURED =
  'Measured is the day Bing was asked for the phrase. A phrase measured within `keywords.maxAgeDays` days of the run keeps its figures and that day, costs no request, and is asked for again once that day is older.';
const SERVED =
  'Served by lists the routes whose target query or title holds every word of the phrase, function words such as a, the, is and what set aside; a dash means no route does.';

const phrasesBuilt = ({ run, unmeasured }) => run.priced + run.carried + unmeasured.length;

export const runLine = (model) =>
  `Run: phrases built ${phrasesBuilt(model)}, priced this run ${model.run.priced}, carried from the cache ${model.run.carried}, never answered ${model.unmeasured.length}`;

export const partialNote = (model) =>
  `Partial run: Bing throttled the key, so it never answered for ${model.unmeasured.length} of ${phrasesBuilt(model)} phrases. They are not zero-volume phrases: their volume is unknown. The report lists them under Not measured, and the next run asks Bing for them again.`;

function headerLines(model) {
  const { window, market, phrases, candidates, run, unmeasured } = model;
  const span = window.startDate === null ? '' : ` (window ${window.startDate} to ${window.endDate})`;
  const withVolume = phrases.filter(({ exact }) => exact > 0).length;
  return [
    `Measured: ${window.measured}${span}`,
    '',
    `Market: country ${market.country}, language ${market.language}`,
    '',
    `Totals: phrases priced ${phrases.length}, with an exact impression ${withVolume}, candidates ${candidates.length}`,
    '',
    runLine(model),
    '',
    ...(unmeasured.length > 0 ? [partialNote(model), ''] : []),
    ...(window.startDate === null ? [run.priced === 0 ? NOTHING_PRICED : NO_WINDOW, ''] : []),
    GENERATED,
    '',
    LIMITS,
    '',
  ];
}

function phrasesSection({ phrases }) {
  const rows = phrases.map(({ phrase, exact, broad, weeks, measured, servedBy }) => [
    cellText(phrase),
    String(exact),
    String(broad),
    String(weeks),
    measured,
    codes(servedBy),
  ]);
  return [
    '## Phrases',
    '',
    `Every phrase with figures, priced this run or carried from an earlier one, most exact impressions first. ${COLUMNS} ${MEASURED} ${SERVED}`,
    '',
    table(['Phrase', 'Exact', 'Broad', 'Weeks', 'Measured', 'Served by'], rows),
    '',
  ];
}

function candidatesSection({ candidates }) {
  const head = ['## Candidates', ''];
  if (candidates.length === 0) {
    return [...head, 'No phrase with an exact impression lacks a route that serves it.', ''];
  }
  const rows = candidates.map(({ phrase, exact, broad }) => [cellText(phrase), String(exact), String(broad)]);
  return [
    ...head,
    `Phrases with an exact impression that no route serves: ${candidates.length}, most first. Each is a phrase people searched for that no route's target query or title covers. This report names them and does not choose among them.`,
    '',
    table(['Phrase', 'Exact', 'Broad'], rows),
    '',
  ];
}

function unmeasuredSection({ unmeasured }) {
  if (unmeasured.length === 0) return [];
  return [
    '## Not measured',
    '',
    `Phrases Bing never answered for: ${unmeasured.length}, in alphabetical order. This report holds no figure for any of them: each is unknown, not zero.`,
    '',
    table(
      ['Phrase'],
      unmeasured.map((phrase) => [cellText(phrase)])
    ),
    '',
  ];
}

export function renderKeywords(model) {
  return [
    '# Keyword demand: what Bing Webmaster Tools measured',
    '',
    ...headerLines(model),
    ...phrasesSection(model),
    ...candidatesSection(model),
    ...unmeasuredSection(model),
  ].join('\n');
}
